149	void TcpStatsdSink::TlsSink::beginFlush(bool expect_empty_buffer) {
150	  ASSERT(!expect_empty_buffer || buffer_.length() == 0);
151	  ASSERT(current_slice_mem_ == nullptr);
152	
153	  uint64_t num_iovecs = buffer_.reserve(FLUSH_SLICE_SIZE_BYTES, &current_buffer_slice_, 1);
154	  ASSERT(num_iovecs == 1);
155	
156	  ASSERT(current_buffer_slice_.len_ >= FLUSH_SLICE_SIZE_BYTES);
157	  current_slice_mem_ = reinterpret_cast<char*>(current_buffer_slice_.mem_);
158	}
